(()=>{'use strict';const body=document.body;if(!body.classList.contains('has-sidebar'))return;const toggle=document.querySelector('.sidebar-toggle'),panel=document.querySelector('#site-sidebar'),backdrop=document.querySelector('.sidebar-backdrop');const mobile=matchMedia('(max-width:1100px)');
const menuItems = panel.querySelectorAll('nav > a, nav > button, nav > .music-control > [data-music-toggle]');
menuItems.forEach((item, index) => {
  const badge = document.createElement('span');
  badge.className = 'sidebar-item-number';
  badge.setAttribute('aria-hidden', 'true');
  badge.textContent = String(index + 1);
  item.prepend(badge);
});
function setOpen(open,restore=false){body.classList.toggle('sidebar-open',open);toggle.setAttribute('aria-expanded',String(open));backdrop.hidden=!open;if(mobile.matches)panel.inert=!open;else panel.inert=false;if(open)panel.querySelector('a')?.focus();else if(restore)toggle.focus();}
toggle.addEventListener('click',()=>setOpen(!body.classList.contains('sidebar-open')));backdrop.addEventListener('click',()=>setOpen(false,true));document.addEventListener('keydown',e=>{if(!body.classList.contains('sidebar-open'))return;if(e.key==='Escape'){setOpen(false,true);return;}if(e.key==='Tab'&&mobile.matches){const list=[...panel.querySelectorAll('a[href],button:not([disabled]),input:not([disabled])')].filter(el=>el.getClientRects().length);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
panel.addEventListener('click',e=>{if(e.target.closest('nav>a')&&mobile.matches)setOpen(false);if(e.target.closest('[data-ui-settings],[data-open-method],[data-ai-help]')&&mobile.matches)setOpen(false);});mobile.addEventListener('change',()=>setOpen(false));setOpen(false);
// Desktop resizing uses one width token shared by the panel, content and progress bar.
const grip=document.createElement('div');grip.className='sidebar-resizer';grip.tabIndex=0;grip.setAttribute('role','separator');grip.setAttribute('aria-orientation','vertical');grip.setAttribute('aria-label','调整侧边栏宽度');grip.title='拖动调整宽度；双击恢复默认；方向键微调';grip.setAttribute('aria-valuemin','220');grip.setAttribute('aria-valuemax','420');body.append(grip);
let width=256,drag=null;function applyWidth(value,save=false){width=Math.min(420,Math.max(220,value));body.style.setProperty('--sidebar-width',width+'px');grip.setAttribute('aria-valuenow',String(width));grip.setAttribute('aria-valuetext',width+'像素');if(save)try{localStorage.setItem('qi-sidebar-width',String(width));}catch{}}
try{const saved=Number(localStorage.getItem('qi-sidebar-width'));if(Number.isFinite(saved)&&saved>=220&&saved<=420)width=saved;}catch{}applyWidth(width);
function finish(){if(!drag)return;drag=null;body.classList.remove('sidebar-resizing');applyWidth(width,true);}
grip.addEventListener('pointerdown',e=>{if(mobile.matches||e.button!==0)return;e.preventDefault();drag={x:e.clientX,width};grip.setPointerCapture(e.pointerId);body.classList.add('sidebar-resizing');});grip.addEventListener('pointermove',e=>{if(drag)applyWidth(drag.width+e.clientX-drag.x);});grip.addEventListener('pointerup',finish);grip.addEventListener('pointercancel',finish);grip.addEventListener('lostpointercapture',finish);mobile.addEventListener('change',finish);window.addEventListener('blur',finish);
grip.addEventListener('dblclick',()=>applyWidth(256,true));grip.addEventListener('keydown',e=>{let next;if(e.key==='ArrowLeft')next=width-(e.shiftKey?30:10);if(e.key==='ArrowRight')next=width+(e.shiftKey?30:10);if(e.key==='Home')next=220;if(e.key==='End')next=420;if(next!==undefined){e.preventDefault();applyWidth(next,true);}});
const links=[...panel.querySelectorAll('nav>a[href^="#"]')];
if('IntersectionObserver'in window){
  const sections=links.map(link=>document.getElementById(link.hash.slice(1))).filter(Boolean);
  const visible=new Set();
  let current=null, observer;
  function updateCurrent(entries){
    for(const entry of entries){
      if(entry.isIntersecting)visible.add(entry.target.id);
      else visible.delete(entry.target.id);
    }
    let next=null;
    for(const link of links)if(visible.has(link.hash.slice(1)))next=link;
    if(next===current)return;
    current?.classList.remove('is-current');
    current?.removeAttribute('aria-current');
    next?.classList.add('is-current');
    next?.setAttribute('aria-current','location');
    current=next;
  }
  function watchSections(){
    observer?.disconnect();
    visible.clear();
    const height=window.innerHeight;
    observer=new IntersectionObserver(updateCurrent,{
      rootMargin:`-${Math.round(height*.24)}px 0px -${Math.round(height*.66)}px 0px`
    });
    sections.forEach(section=>observer.observe(section));
  }
  watchSections();
  window.addEventListener('resize',watchSections);
}
})();
